			{
				Main.screenWidth = GraphicsAdapter.DefaultAdapter.CurrentDisplayMode.Width;
			}
			if (Main.screenHeight > GraphicsAdapter.DefaultAdapter.CurrentDisplayMode.Height)
			{
				Main.screenHeight = GraphicsAdapter.DefaultAdapter.CurrentDisplayMode.Height;
			}
			this.UpdateDisplaySettings();
			Main.graphics.ApplyChanges();
			if (Main.OnResolutionChanged != null)
			{
				Main.OnResolutionChanged(new Vector2((float)Main.screenWidth, (float)Main.screenHeight));
			}
			this.CheckBunny();
			base.GraphicsDevice.DeviceLost += this.GraphicsDeviceLost;
			base.GraphicsDevice.DeviceReset += this.GraphicsDeviceLost;
			base.GraphicsDevice.DeviceResetting += this.GraphicsDeviceLost;
			if (Main._needsLanguageSelect)
			{
				Main.menuMode = 1212;
			}
			this._achievements = new AchievementManager();
			this._achievementAdvisor = new AchievementAdvisor();
			this.OpenRecent();
			UILinksInitializer.Load();
			Main.Chroma = new ChromaEngine();
			Main.ChromaPainter = new ChromaHotkeyPainter();
			Main.ChromaPainter.CollectBoundKeys();
			Main.CacheSupportedDisplaySizes();
			if (Main.autoJoin)
			{
				Main.menuMode = 1;
				Main.menuMultiplayer = true;
			}
			Main.fpsTimer.Start();
		}

		// Token: 0x06000C70 RID: 3184 RVA: 0x0036866C File Offset: 0x0036686C
		private static void CacheSupportedDisplaySizes()
		{
			Main.numDisplayModes = 0;
			Main.CollectDisplayResolutionsFromAdapter(GraphicsAdapter.DefaultAdapter);
			foreach (GraphicsAdapter graphicsAdapter in GraphicsAdapter.Adapters)
			{
				if (graphicsAdapter != GraphicsAdapter.DefaultAdapter)
				{
					Main.CollectDisplayResolutionsFromAdapter(graphicsAdapter);
				}
			}
			if (Main.numDisplayModes == 0)
			{
				Main.RegisterDisplayResolution(Main.minScreenW, Main.minScreenH);
			}
		}

		// Token: 0x06000C71 RID: 3185 RVA: 0x003686E8 File Offset: 0x003668E8
		private static void CollectDisplayResolutionsFromAdapter(GraphicsAdapter adapter)
		{
			foreach (DisplayMode displayMode in adapter.SupportedDisplayModes)
			{
				if (displayMode.Width >= Main.minScreenW && displayMode.Width <= Main.maxScreenW && displayMode.Height >= Main.minScreenH && displayMode.Height <= Main.maxScreenH && !Main.IsModeOfSameResolutionRegistered(displayMode))
				{
					Main.RegisterDisplayResolution(displayMode.Width, displayMode.Height);
				}
			}
		}

		// Token: 0x06000C72 RID: 3186 RVA: 0x0036877C File Offset: 0x0036697C
		private static void RegisterDisplayResolution(int width, int height)
		{
			if (Main.numDisplayModes >= Main.displayWidth.Length)
			{
				Array.Resize<int>(ref Main.displayWidth, Main.numDisplayModes * 2);
				Array.Resize<int>(ref Main.displayHeight, Main.numDisplayModes * 2);
			}
			Main.displayWidth[Main.numDisplayModes] = width;
			Main.displayHeight[Main.numDisplayModes] = height;
			Main.numDisplayModes++;
		}

		// Token: 0x06000C73 RID: 3187 RVA: 0x003687E0 File Offset: 0x003669E0
		private static bool IsModeOfSameResolutionRegistered(DisplayMode mode)
		{
			for (int i = 0; i < Main.numDisplayModes; i++)
			{
				if (mode.Width == Main.displayWidth[i] && mode.Height == Main.displayHeight[i])
				{
					return true;
				}
			}
			return false;
		}

