		// Token: 0x06000D5C RID: 3420 RVA: 0x003C664C File Offset: 0x003C484C
		public static int GetNurseHealCost()
		{
			int num = Main.player[Main.myPlayer].statLifeMax2 - Main.player[Main.myPlayer].statLife;
			for (int i = 0; i < Player.maxBuffs; i++)
			{
				int num2 = Main.player[Main.myPlayer].buffType[i];
				if (Main.debuff[num2] && Main.player[Main.myPlayer].buffTime[i] > 60 && (num2 < 0 || num2 >= BuffID.Count || !BuffID.Sets.NurseCannotRemoveDebuff[num2]))
				{
					num += 100;
				}
			}
			if (NPC.downedGolemBoss)
			{
				num *= 200;
			}
			else if (NPC.downedPlantBoss)
			{
				num *= 150;
			}
			else if (NPC.downedMechBossAny)
			{
				num *= 100;
			}
			else if (Main.hardMode)
			{
				num *= 60;
			}
			else if (NPC.downedBoss3 || NPC.downedQueenBee)
			{
				num *= 25;
			}
			else if (NPC.downedBoss2)
			{
				num *= 10;
			}
			else if (NPC.downedBoss1)
			{
				num *= 3;
			}
			if (Main.expertMode)
			{
				num *= 2;
			}
			if (Main.LocalPlayer.discountAvailable)
			{
				num = (int)((float)num * 0.8f);
			}
			return (int)((float)num * Main.LocalPlayer.currentShoppingSettings.PriceAdjustment);
		}

