			bool flag = false;
			// 移除每日完成限制，允许无限提交任务
			if (!Main.anglerQuestFinished && !Main.anglerWhoFinishedToday.Contains(Main.player[Main.myPlayer].name))
			{
				int num = Main.player[Main.myPlayer].FindItem(Main.anglerQuestItemNetIDs[Main.anglerQuest]);
				if (num != -1)
				{
					Main.player[Main.myPlayer].inventory[num].stack--;
					if (Main.player[Main.myPlayer].inventory[num].stack <= 0)
					{
						Main.player[Main.myPlayer].inventory[num] = new Item();
					}
					flag = true;
					SoundEngine.PlaySound(24, -1, -1, 1, 1f, 0f);
					Main.player[Main.myPlayer].anglerQuestsFinished++;
